+              && equal(ref_counts_tokens.index(j), 0)
+        by {
+            assert(ref_counts_tokens.dom().contains(j));
+            assert(equal(ref_counts_tokens.index(j), 0));
+        }
+        assert(forall|j: int|
+            #![trigger( ref_counts_tokens.dom().contains(j) )]
